package edu.seu.vcampus.common.course;
import java.io.*; import java.math.BigDecimal; import java.util.Objects;
/** Optimistically updates a catalog course. */
public record UpdateCourseCommand(String courseId,String courseCode,String courseName,BigDecimal credit,int totalHours,String description,boolean active,long expectedVersion) implements Serializable { @Serial private static final long serialVersionUID=1L; public UpdateCourseCommand { Objects.requireNonNull(courseId);Objects.requireNonNull(courseCode);Objects.requireNonNull(courseName);Objects.requireNonNull(credit);CourseValidation.text("courseId",courseId,36);CourseValidation.text("courseCode",courseCode,24);CourseValidation.text("courseName",courseName,128);if(credit.signum()<=0||totalHours<=0||expectedVersion<0)throw new IllegalArgumentException("invalid course"); } }
